#include <vector>
#include <string>
#include <algorithm>

class Solution {
public:
    int maxDistance(std::vector<std::string>& words) {
        int n = words.size();
        int max_dist = 0;

        for (int i = n - 1; i >= 0; --i) {
            if (words[i] != words[0]) {
                max_dist = std::max(max_dist, i);
                break;
            }
        }
        for (int i = 0; i < n; ++i) {
            if (words[i] != words[n - 1]) {
                max_dist = std::max(max_dist, n - 1 - i);
                break;
            }
        }
        return max_dist;
    }
};

class Solution {
    public int maxDistance(String[] words) {
        int n = words.length;
        int maxDist = 0;

        for (int i = n - 1; i >= 0; i--) {
            if (!words[i].equals(words[0])) {
                maxDist = Math.max(maxDist, i);
                break;
            }
        }
        for (int i = 0; i < n; i++) {
            if (!words[i].equals(words[n - 1])) {
                maxDist = Math.max(maxDist, n - 1 - i);
                break;
            }
        }
        return maxDist;
    }
}

var maxDistance = function(words) {
    const n = words.length;
    let maxDist = 0;

    for (let i = n - 1; i >= 0; i--) {
        if (words[i] !== words[0]) {
            maxDist = Math.max(maxDist, i);
            break;
        }
    }
    for (let i = 0; i < n; i++) {
        if (words[i] !== words[n - 1]) {
            maxDist = Math.max(maxDist, n - 1 - i);
            break;
        }
    }
    return maxDist;
};
